Sort the bookings by start time, then sweep with a min-heap of end times. For each booking, if the earliest end is less than or equal to the current start, pop it, since that room is free. Push the current end, and the heap size is the answer.

That's O(n log n) time and O(n) space. Empty input gives 0.

```js
function minRooms(bookings) {
  if (bookings.length === 0) return 0;
  const sorted = [...bookings].sort((a, b) => a[0] - b[0]);
  const heap = []; // min-heap of end times

  const push = (x) => {
    heap.push(x);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p] <= heap[i]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };

  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      while (true) {
        const l = 2 * i + 1, r = 2 * i + 2;
        let m = i;
        if (l < heap.length && heap[l] < heap[m]) m = l;
        if (r < heap.length && heap[r] < heap[m]) m = r;
        if (m === i) break;
        [heap[i], heap[m]] = [heap[m], heap[i]];
        i = m;
      }
    }
    return top;
  };

  let rooms = 0;
  for (const [start, end] of sorted) {
    if (heap.length > 0 && heap[0] <= start) pop();
    push(end);
    rooms = Math.max(rooms, heap.length);
  }
  return rooms;
}
```

The `<=` is what lets a booking starting exactly when another ends reuse the room. A simpler alternative is to sort starts and ends separately and sweep two pointers, which is also O(n log n) but avoids the heap.

